function assemble_full_replay()
%ASSEMBLE_FULL_REPLAY Copy the actual model algorithms, omit physical IO only.
root=stampfly_project_root();init_official;bench='StampFly_Official_Bench400';m='StampFly_Official_FullReplay400';
if ~bdIsLoaded(m),new_system(m);open_system(m);end
ops={cfg(['config:' m],struct('Solver','FixedStepDiscrete','FixedStep','Official.Step','StopTime','FullReplayStop','SaveOutput','on','OutputSaveName','yout','SaveFormat','Dataset')), ...
 add('FromWorkspace','Trace23','trace',struct('VariableName','FullReplayTrace','Interpolate','off','SampleTime','Official.Step')), ...
 add('MATLABSystem','TypedTrace','input',struct('System','official.FullReplayInput400')), ...
 add(Simulink.ID.getFullName([bench ':530']),'Supervisor','sup',struct), ...
 add(Simulink.ID.getFullName([bench ':531']),'FlipSequence','flip',struct), ...
 add(Simulink.ID.getFullName([bench ':92']),'FlightControl','ctrl',struct), ...
 add('UnitDelay','ModeMemory','mode',struct('SampleTime','Official.Step','InitialCondition','uint8(0)')), ...
 add('UnitDelay','ResetMemory','reset',struct('SampleTime','Official.Step','InitialCondition','false')), ...
 add('UnitDelay','RateMemory','rate',struct('SampleTime','Official.Step','InitialCondition','zeros(3,1,''single'')')), ...
 add('Constant','Zero8','zero',struct('Value','uint8(0)')),add('Mux','Flags','flags',struct('Inputs','3')), ...
 add('Outport','Duty','duty',struct('Port','1')),add('Outport','Diagnostics','diag',struct('Port','2')),add('Outport','Mode','state',struct('Port','3')), ...
 add('Outport','AltFlag','alt',struct('Port','4')),add('Outport','FlipFlag','phase',struct('Port','5')),add('Outport','Branch','branch',struct('Port','6')), ...
 wire('#trace.y1','#input.u1'),wire('#input.y8','#flags.u1'),wire('#zero.y1','#flags.u2'),wire('#zero.y1','#flags.u3'), ...
 wire('#mode.y1','#sup.u1'),wire('#input.y10','#sup.u2'),wire('#input.y12','#sup.u3'),wire('#flags.y1','#sup.u4'),wire('#input.y13','#sup.u5'), ...
 wire('#input.y11','#flip.u1'),wire('#sup.y1','#flip.u2'),wire('#input.y6','#flip.u3'),wire('#reset.y1','#flip.u4'),wire('#rate.y1','#flip.u5')};
src={'#input.y1','#input.y2','#input.y3','#input.y4','#input.y5','#input.y6','#input.y7','#input.y8','#sup.y1','#input.y9','#sup.y2','#flip.y3','#flip.y4','#flip.y5','#flip.y1','#flip.y2','#flip.y6'};
for k=1:17,ops{end+1}=wire(src{k},['#ctrl.u' num2str(k)]);end
ops=[ops,{wire('#ctrl.y1','#duty.u1'),wire('#ctrl.y3','#diag.u1'),wire('#ctrl.y4','#alt.u1'),wire('#ctrl.y5','#phase.u1'),wire('#ctrl.y6','#reset.u1'),wire('#ctrl.y7','#rate.u1'),wire('#ctrl.y8','#mode.u1'),wire('#ctrl.y8','#state.u1'),wire('#sup.y1','#branch.u1')}];
unused={'#sup.y3','#sup.y4','#sup.y5','#flip.y7','#flip.y8','#ctrl.y2'};
for k=1:numel(unused),ops=[ops,{add('Terminator',['Unused' num2str(k)],['t' num2str(k)],struct),wire(unused{k},['#t' num2str(k) '.u1'])}];end
model_read(m,'root','0');disp(model_edit(m,'root',jsonencode(ops),'full'));model_check(m,'root','["all"]');save_system(m,stampfly_model_file(m));
end
function op=add(type,name,ref,params),op=struct('op','add_block','type',type,'name',name,'ref',ref,'params',params);end
function op=wire(a,b),op=struct('op','connect','target',[a ' -> ' b]);end
function op=cfg(target,params),op=struct('op','configure','target',target,'params',params);end
